using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalFountainDetail{
static FinalFountainDetail(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalFountainDetail.request")||EditorApplication.isCompiling)return;File.Delete("FinalFountainDetail.request");Run();}
static void Photo(UnityEngine.SceneManagement.Scene s,Vector3 p,Vector3 target,string n)=>typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{s,p,target,n});
static void Run(){try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var fountains=root.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith("Fountain_")).ToArray();int added=0;foreach(var f in fountains){var m=f.sharedMesh;var collider=f.GetComponent<MeshCollider>().sharedMesh;string backup="FinalEnvironmentRoadBackup/FountainDetail-20261012/"+m.name+".asset";if(!File.Exists(backup))File.Copy(AssetDatabase.GetAssetPath(m),backup);var p=m.vertices.ToList();var n=m.normals.ToList();var uv=m.uv.ToList();var info=m.uv2.ToList();var colors=m.colors.ToList();var ids=m.triangles.ToList();var plot=new List<Vector2>();var centers=new List<Vector2>();m.GetUVs(3,plot);m.GetUVs(4,centers);if(!colors.Any(c=>c.r<-.5)){var random=new System.Random(2747);var water=new List<Vector3>();for(int j=0;j<p.Count;j++)if(info[j].x==13&&j+2<p.Count){water.Add(p[j]);j+=2;}var tiers=water.Distinct().OrderBy(v=>v.y).ToArray();var center=tiers[0];float radius=Vector3.Distance(center,p[Array.FindIndex(m.uv2,v=>v.x==13)+1]);for(int k=0;k<72;k++){int tier=k%3;var anchor=tiers[Mathf.Min(tier,tiers.Length-1)];float a=(float)random.NextDouble()*Mathf.PI*2;float r=tier==0?radius*.43f:tier==1?radius*.23f:.12f;anchor+=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a))*r;float size=.035f+(float)random.NextDouble()*.055f;var right=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a))*size;var top=Vector3.up*size*2;int i=p.Count;p.AddRange(new[]{anchor-right,anchor+right,anchor+right+top,anchor-right+top});n.AddRange(Enumerable.Repeat(Vector3.up,4));uv.AddRange(new[]{Vector2.zero,Vector2.right,Vector2.one,Vector2.up});info.AddRange(Enumerable.Repeat(new Vector2(14,3),4));colors.AddRange(Enumerable.Repeat(new Color(-1,(float)random.NextDouble(),1,14.5f/16),4));plot.AddRange(Enumerable.Repeat(new Vector2(Mathf.Cos(a),Mathf.Sin(a))*(.25f+(float)random.NextDouble()*.65f),4));centers.AddRange(Enumerable.Repeat(Vector2.zero,4));ids.AddRange(new[]{i,i+1,i+2,i,i+2,i+3});added+=2;}
m.SetVertices(p);m.SetNormals(n);m.SetUVs(0,uv);m.SetUVs(1,info);m.SetUVs(3,plot);m.SetUVs(4,centers);m.SetColors(colors);m.SetTriangles(ids,0);m.RecalculateBounds();var b=m.bounds;b.Expand(4);m.bounds=b;EditorUtility.SetDirty(m);}if(collider!=f.GetComponent<MeshCollider>().sharedMesh)throw new Exception("Collider changed");}
AssetDatabase.SaveAssets();Shader.SetGlobalFloat("_CityGardenPreviewEnabled",1);try{foreach(var f in fountains){var p=f.GetComponent<Renderer>().bounds.center;for(int frame=0;frame<2;frame++){Shader.SetGlobalFloat("_CityGardenPreviewTime",frame*1.25f);Photo(scene,p+new Vector3(8,6,-9),p,"Fountain-Detail-"+f.name+"-"+frame);}}}finally{Shader.SetGlobalFloat("_CityGardenPreviewEnabled",0);}var shader=fountains[0].GetComponent<Renderer>().sharedMaterial.shader;int errors=ShaderUtil.GetShaderMessages(shader).Count(v=>v.severity.ToString()=="Error");if(errors>0)throw new Exception("Shader errors="+errors);File.WriteAllText("FinalEnvironmentRoadReview/FountainDetailReport.txt","SUCCESS: two fountains; spray triangles added="+added+"; irregular moving foam, fine streams and layered water detail; existing shared atlas/material/batches retained; collider unchanged; no particle system, reflection camera or new realtime light; shader errors=0");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/FountainDetailReport.txt","FAILED "+e);Debug.LogException(e);}}}
